export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [];
	if (min > max) [min, max] = [max, min];
	if (min === max) return [0];
	const raw = (max - min) / 5;
	const power = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / power;
	const factor = norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10;
	const step = factor * power;
	const ticks: number[] = [];
	const start = Math.ceil(min / step) * step;
	for (let v = start; v <= max; v += step) {
		ticks.push(Math.round(v * 1e10) / 1e10);
	}
	if (!ticks.includes(0) && min <= 0 && max >= 0) {
		ticks.push(0);
		ticks.sort((a, b) => a - b);
	}
	return ticks;
}

export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const y = d.getUTCFullYear();
	const m = String(d.getUTCMonth() + 1).padStart(2, "0");
	const day = String(d.getUTCDate()).padStart(2, "0");
	return `${y}.${m}.${day}`;
}

function carryPercent(values: (number | null | undefined)[]): number[] {
	let last = 0;
	return values.map((v) => {
		if (v != null && Number.isFinite(v)) last = v * 100;
		return last;
	});
}

export function curveView(trial: ScreenTrial | undefined | null) {
	const c = trial?.curve;
	if (!c || !c.t || c.t.length < 2) return null;
	const rule = carryPercent(c.rule ?? []);
	const hold = carryPercent(c.hold ?? []);
	const all = [...rule, ...hold];
	const min = Math.min(...all);
	const max = Math.max(...all);
	return {
		t: c.t,
		labels: c.t.map(dateLabel),
		rule,
		hold,
		ticks: niceTicks(min, max),
		min,
		max,
	};
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign;
	const effective = fixed ?? trial.train_sign;
	const long = effective >= 0;
	const signs = new Set((trial.folds ?? []).map((f) => Math.sign(f.train_sign)));
	const changed = signs.size > 1;
	const label = changed ? "부호 바뀜" : long ? "순방향" : "역추세";
	const directionTip = fixed != null
		? `부호를 ${fixed > 0 ? "+1" : "−1"}로 고정한다 (${fixed > 0 ? "+1" : "-1"}로 고정).`
		: changed
			? "연도마다 학습 부호가 달라 부호가 바뀐다."
			: long
				? "학습 부호가 양수라 지표가 기준 위면 롱, 아래면 숏이다."
				: "학습 부호가 음수라 지표가 기준 위면 숏, 아래면 롱이다.";
	const tiles: ScreenRuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			name: featureName(feature),
			label: feature.tradeable === false ? "참고 지표" : "지표",
			tip: featureDef(feature) || feature.feature,
		},
		{
			id: "direction",
			group: "entry",
			name: long ? "기준 위면 롱" : "기준 위면 숏",
			label,
			tip: directionTip,
		},
		{
			id: "fill",
			group: "fill",
			name: `편도 ${Math.round(doc.cost_per_side * 1e4)}bp`,
			label: "비용",
			tip: `편도 ${Math.round(doc.cost_per_side * 1e4)}bp를 비용으로 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유",
			tip: `${trial.h}${doc.unit} 뒤에 청산한다.`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락 장세만",
			label: "레짐",
			tip: "종가가 200일 평균 아래인 날만 매매한다.",
		});
	}
	return tiles;
}

